String clockLabel(int? m) {
  if (m == null) return 'null';
  final h = m ~/ 60, min = m % 60;
  final h12 = h % 12 == 0 ? 12 : h % 12;
  return '$h12:${min.toString().padLeft(2, '0')} ${h < 12 ? 'AM' : 'PM'}';
}

void main() {
  IntegrationTestWidgetsFlutterBinding.ensureInitialized();

  late String imagePath;

  setUpAll(() async {
    final tmp = Directory.systemTemp.createTempSync('mlkit_ocr_');
    final file = File('${tmp.path}/timetable.jpg');
    await file.writeAsBytes(base64Decode(timetableJpegB64));
    imagePath = file.path;
    debugPrint('ML Kit test image written to: $imagePath');
  });

  group('ML Kit on-device OCR', () {
    testWidgets('raw OCR text is non-empty for timetable image', (tester) async {
      final scanner = MosqueTimetableScanner();
      final raw = await scanner.scanRaw(imagePath);

      debugPrint('\n=== Raw ML Kit OCR text ===');
      debugPrint(raw.isEmpty ? '(empty — ML Kit could not read the font)' : raw);
      debugPrint('===========================\n');

      expect(raw.trim(), isNotEmpty,
          reason: 'ML Kit returned empty text for the generated timetable image');
    });

    testWidgets('scanner detects ≥4 of 5 prayers from timetable image', (tester) async {
      final scanner = MosqueTimetableScanner();
      final scan = await scanner.scan(imagePath);

      debugPrint('\n======= ML Kit scan result =======');
      for (final p in PrayerName.obligatory) {
        debugPrint('  ${p.name.padRight(8)}: ${clockLabel(scan[p])}');
      }
      debugPrint('==================================\n');

      final detected = scan.values.where((v) => v != null).length;
      expect(detected, greaterThanOrEqualTo(4),
          reason: 'Only $detected/5 prayers detected');

      void expectNear(PrayerName prayer, int expectedMin) {
        final got = scan[prayer];
        if (got == null) return;
        expect((got - expectedMin).abs(), lessThanOrEqualTo(5),
            reason: '${prayer.name}: want ~${clockLabel(expectedMin)}, got ${clockLabel(got)}');
      }

      expectNear(PrayerName.fajr, 5 * 60 + 30);
      expectNear(PrayerName.dhuhr, 13 * 60 + 30);
      expectNear(PrayerName.asr, 16 * 60 + 0);
      expectNear(PrayerName.maghrib, 18 * 60 + 27);
      expectNear(PrayerName.isha, 20 * 60 + 45);
    });

    testWidgets('scanner does not crash on a plain-text file (returns all-null)', (tester) async {
      // Write a plain-text file with a .jpg extension — ML Kit will fail to decode
      // the image header and either return empty text or throw a PlatformException.
      // Either outcome is acceptable; what is NOT acceptable is a crash.
      final tmp = Directory.systemTemp.createTempSync('mlkit_blank_');
      final blank = File('${tmp.path}/blank.jpg');
      await blank.writeAsString('not a jpeg');

      final scanner = MosqueTimetableScanner();
      try {
        final scan = await scanner.scan(blank.path);
        expect(scan.values.any((v) => v != null), isFalse,
            reason: 'Corrupt image unexpectedly detected prayers');
      } on PlatformException {
        // Acceptable: ML Kit rejects unreadable images on some Android versions.
      }
    });
  });
}
